command:
// Installe les macros de la Bascule d'époque et du Suivi du groupe (CoC7), avec leurs icônes.
// Relancer cette macro met à jour les macros déjà créées (même nom) au lieu de les dupliquer.
if (!game.user.isGM) return ui.notifications.warn("Réservé au Gardien.");
const MACROS = [
  {
    "name": "Bascule d'époque",
    "img": "modules/coc7-bascule-epoque/icons/macros/bascule-epoque.svg",
    "command": "const mod = game.modules.get(\"coc7-bascule-epoque\");\nif (!mod?.active) return ui.notifications.warn(\"Le module « Bascule d'époque » n'est pas activé.\");\nmod.api.open(\"epoques\");",
    "joueurs": false
  },
  {
    "name": "Passer en 1933",
    "img": "modules/coc7-bascule-epoque/icons/macros/bascule-1933.svg",
    "command": "const mod = game.modules.get(\"coc7-bascule-epoque\");\nif (!mod?.active) return ui.notifications.warn(\"Le module « Bascule d'époque » n'est pas activé.\");\nmod.api.switchEra(\"1933\");",
    "joueurs": false
  },
  {
    "name": "Passer en 2025-2026",
    "img": "modules/coc7-bascule-epoque/icons/macros/bascule-2026.svg",
    "command": "const mod = game.modules.get(\"coc7-bascule-epoque\");\nif (!mod?.active) return ui.notifications.warn(\"Le module « Bascule d'époque » n'est pas activé.\");\nmod.api.switchEra(\"modern\");",
    "joueurs": false
  },
  {
    "name": "Personnages par époque",
    "img": "modules/coc7-bascule-epoque/icons/macros/bascule-personnages.svg",
    "command": "const mod = game.modules.get(\"coc7-bascule-epoque\");\nif (!mod?.active) return ui.notifications.warn(\"Le module « Bascule d'époque » n'est pas activé.\");\nmod.api.open(\"personnages\");",
    "joueurs": false
  },
  {
    "name": "Réglages des époques",
    "img": "modules/coc7-bascule-epoque/icons/macros/bascule-reglages.svg",
    "command": "const mod = game.modules.get(\"coc7-bascule-epoque\");\nif (!mod?.active) return ui.notifications.warn(\"Le module « Bascule d'époque » n'est pas activé.\");\nmod.api.open(\"reglages\");",
    "joueurs": false
  },
  {
    "name": "Suivi du groupe",
    "img": "modules/coc7-suivi-groupe/icons/macros/suivi-groupe.svg",
    "command": "const mod = game.modules.get(\"coc7-suivi-groupe\");\nif (!mod?.active) return ui.notifications.warn(\"Le module « Suivi du groupe » n'est pas activé.\");\nmod.api.basculer();",
    "joueurs": false
  },
  {
    "name": "Suivi : Chance",
    "img": "modules/coc7-suivi-groupe/icons/macros/suivi-chance.svg",
    "command": "const mod = game.modules.get(\"coc7-suivi-groupe\");\nif (!mod?.active) return ui.notifications.warn(\"Le module « Suivi du groupe » n'est pas activé.\");\nmod.api.ouvrir(\"chance\");",
    "joueurs": false
  },
  {
    "name": "Suivi : Santé mentale",
    "img": "modules/coc7-suivi-groupe/icons/macros/suivi-san.svg",
    "command": "const mod = game.modules.get(\"coc7-suivi-groupe\");\nif (!mod?.active) return ui.notifications.warn(\"Le module « Suivi du groupe » n'est pas activé.\");\nmod.api.ouvrir(\"san\");",
    "joueurs": false
  },
  {
    "name": "Suivi : Liens",
    "img": "modules/coc7-suivi-groupe/icons/macros/suivi-liens.svg",
    "command": "const mod = game.modules.get(\"coc7-suivi-groupe\");\nif (!mod?.active) return ui.notifications.warn(\"Le module « Suivi du groupe » n'est pas activé.\");\nmod.api.ouvrir(\"liens\");",
    "joueurs": false
  },
  {
    "name": "Suivi : Poursuite",
    "img": "modules/coc7-suivi-groupe/icons/macros/suivi-poursuite.svg",
    "command": "const mod = game.modules.get(\"coc7-suivi-groupe\");\nif (!mod?.active) return ui.notifications.warn(\"Le module « Suivi du groupe » n'est pas activé.\");\nmod.api.ouvrir(\"poursuite\");",
    "joueurs": false
  },
  {
    "name": "Jauge de poursuite",
    "img": "modules/coc7-suivi-groupe/icons/macros/suivi-jauge.svg",
    "command": "const mod = game.modules.get(\"coc7-suivi-groupe\");\nif (!mod?.active) return ui.notifications.warn(\"Le module « Suivi du groupe » n'est pas activé.\");\nmod.api.jauge();",
    "joueurs": true
  }
];
const NOM_DOSSIER = "Outils CoC7";
let dossier = game.folders.find((f) => f.type === "Macro" && f.name === NOM_DOSSIER);
dossier ??= await Folder.create({ name: NOM_DOSSIER, type: "Macro", color: "#4fb3a6" });
let crees = 0, maj = 0;
for (const m of MACROS) {
  const data = { name: m.name, type: "script", img: m.img, command: m.command, folder: dossier.id };
  if (m.joueurs) data.ownership = { default: CONST.DOCUMENT_OWNERSHIP_LEVELS.OBSERVER };
  const deja = game.macros.find((x) => x.name === m.name && x.folder?.id === dossier.id);
  if (deja) { await deja.update(data); maj++; } else { await Macro.create(data); crees++; }
}
ui.notifications.info(`Macros CoC7 : ${crees} créée(s), ${maj} mise(s) à jour, dans le dossier « ${NOM_DOSSIER} ».`);
ui.macros?.activate?.();
